// Shape of public/assets/field-layout.json (generated by tools/convert-field.mjs from the REBUILT
// field CAD). Units: meters, Y up, origin at the field center on the carpet. Red ALLIANCE WALL at -X;
// the blue half is the red one turned half a turn about the center.

export type Vec3 = [number, number, number];

export interface Box3 {
  min: Vec3;
  max: Vec3;
}

export type ElementName =
  | 'hub_red' | 'hub_blue' | 'tower_red' | 'tower_blue' | 'outpost_red' | 'outpost_blue'
  | 'depot_red' | 'depot_blue' | 'bumps' | 'trenches' | 'perimeter';

export interface FieldLayout {
  /** Distance from the field center to the inner faces of the ALLIANCE WALLS (x) and guardrails (z) */
  wall: { halfX: number; halfZ: number };
  /** Each field element's bounding box */
  elements: Record<ElementName, Box3> & Record<string, Box3>;
}

/** FUEL: a 15 cm foam ball (manual 5.10.1) */
export const FUEL_RADIUS = 0.075;
